// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the factorization was successful.
* -   if greater than zero, then `U(k, k)` is exactly zero, where `k = StatusCode-1`. The factorization has been completed, but the factor `U` is exactly singular, and division by zero will occur if the factor is used to solve a system of equations.
*/
type StatusCode = number;

/**
* Interface describing `dgetf2`.
*/
interface Routine {
	/**
	* Computes the LU factorization of a general M-by-N matrix A using partial pivoting with row interchanges.
	*
	* ## Notes
	*
	* -   `A` is overwritten by the factors `L` and `U`, where the unit diagonal elements of `L` are not stored.
	* -   `IPIV` should have at least `min(M,N)` indexed elements and is overwritten by the pivot indices. Pivot indices are 0-based. For `0 <= i < min(M,N)`, row `i` of the matrix was interchanged with row `IPIV(i)`.
	*
	* @param order - storage layout of `A`
	* @param M - number of rows in matrix `A`
	* @param N - number of columns in matrix `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A` if column-major, or stride between rows if row-major)
	* @param IPIV - vector of pivot indices
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 2.0, 1.0, 4.0, 6.0 ] );
	* var IPIV = new Int32Array( 2 );
	*
	* var info = dgetf2( 'row-major', 2, 2, A, 2, IPIV );
	* // info => 0
	*/
	( order: Layout, M: number, N: number, A: Float64Array, LDA: number, IPIV: Int32Array ): StatusCode;

	/**
	* Computes the LU factorization of a general M-by-N matrix A using partial pivoting with row interchanges and alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `A` is overwritten by the factors `L` and `U`, where the unit diagonal elements of `L` are not stored.
	* -   `IPIV` should have at least `min(M,N)` indexed elements and is overwritten by the pivot indices. Pivot indices are 0-based. For `0 <= i < min(M,N)`, row `i` of the matrix was interchanged with row `IPIV(i)`.
	*
	* @param M - number of rows in matrix `A`
	* @param N - number of columns in matrix `A`
	* @param A - input matrix
	* @param strideA1 - row stride of `A`
	* @param strideA2 - column stride of `A`
	* @param offsetA - starting index of `A`
	* @param IPIV - vector of pivot indices
	* @param strideIPIV - stride length for `IPIV`
	* @param offsetIPIV - starting index of `IPIV`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 2.0, 1.0, 4.0, 6.0 ] );
	* var IPIV = new Int32Array( 2 );
	*
	* var info = dgetf2.ndarray( 2, 2, A, 2, 1, 0, IPIV, 1, 0 );
	* // info => 0
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, IPIV: Int32Array, strideIPIV: number, offsetIPIV: number ): StatusCode;
}

/**
* Computes the LU factorization of a general M-by-N matrix A using partial pivoting with row interchanges.
*
* ## Notes
*
* -   `A` is overwritten by the factors `L` and `U`, where the unit diagonal elements of `L` are not stored.
* -   `IPIV` should have at least `min(M,N)` indexed elements and is overwritten by the pivot indices. Pivot indices are 0-based. For `0 <= i < min(M,N)`, row `i` of the matrix was interchanged with row `IPIV(i)`.
*
* @param order - storage layout of `A`
* @param M - number of rows in matrix `A`
* @param N - number of columns in matrix `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A` if column-major, or stride between rows if row-major)
* @param IPIV - vector of pivot indices
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 2.0, 1.0, 4.0, 6.0 ] );
* var IPIV = new Int32Array( 2 );
*
* var info = dgetf2( 'row-major', 2, 2, A, 2, IPIV );
* // info => 0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 2.0, 1.0, 4.0, 6.0 ] );
* var IPIV = new Int32Array( 2 );
*
* var info = dgetf2.ndarray( 2, 2, A, 2, 1, 0, IPIV, 1, 0 );
* // info => 0
*/
declare var dgetf2: Routine;


// EXPORTS //

export = dgetf2;
